<?php
namespace Tests\Feature;use App\Models\Order;use App\Services\OrderLifecycleService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class Pack010OrderCareTest extends TestCase{use RefreshDatabase;private function order():Order{return Order::create(['uuid'=>(string)Str::uuid(),'number'=>'TRACK-1','status'=>'confirmed','payment_status'=>'cod_pending','currency'=>'BDT','subtotal'=>100,'grand_total'=>100,'customer_name'=>'Buyer','phone'=>'01700000000','country_code'=>'BD','city'=>'Dhaka','address'=>'Address']);}public function test_customer_can_track_with_order_and_phone():void{$this->seed();$o=$this->order();app(OrderLifecycleService::class)->transition($o,'processing');$this->post(route('orders.track'),['number'=>'TRACK-1','phone'=>'01700000000'])->assertOk()->assertSee('processing');}public function test_wrong_phone_cannot_reveal_order():void{$this->seed();$this->order();$this->post(route('orders.track'),['number'=>'TRACK-1','phone'=>'wrong'])->assertNotFound();}}
